class ThreeBeeps:
    def __init__(self):
        self.left = 3

    def __iter__(self):
        return self            # the object is its own iterator

    def __next__(self):
        if self.left == 0:
            raise StopIteration
        self.left -= 1
        return "beep"

for b in ThreeBeeps():
    print(b)

