def tank_drain(start):
    level = start
    while level >= 0:      # report first, drain after
        yield level
        level -= 3


def drain_log(start):
    return list(tank_drain(start))

from itertools import islice


def label_stream():
    number = 1
    while True:                 # the course never closes
        for letter in "ABC":    # letters cycle within one number
            yield letter + str(number)
        number += 1


def checkpoint_labels(count):
    return list(islice(label_stream(), count))

