from itertools import islice


class FibCounter:
    """A Fibonacci-style counter with a yield limit and a reset."""

    def __init__(self, a, b, limit):
        self._seed = (a, b)
        self._limit = limit
        self.reset(a, b)

    def __iter__(self):
        return self

    def __next__(self):
        if self._given >= self._limit:
            raise StopIteration          # exhausted stays exhausted
        value = self._current
        self._current, self._following = (self._following,
                                          self._current + self._following)
        self._given += 1
        return value

    def reset(self, x, y):
        self._current = x
        self._following = y
        self._given = 0                 # full budget restored


def fib_session(a, b, limit, ops):
    counter = FibCounter(a, b, limit)
    recorded = []
    for op in ops:
        if op[0] == "take":
            recorded.extend(islice(counter, op[1]))
        elif op[0] == "skip":
            for _ in islice(counter, op[1]):
                pass                      # advance, record nothing
        else:                              # ["reset", x, y]
            counter.reset(op[1], op[2])
    return recorded
